<?php require_once __DIR__.'/../includes/admin-auth.php';require_admin(['super_admin','event_admin','checkin_staff']);header('Content-Type: application/json; charset=utf-8');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);echo json_encode(['ok'=>false,'message'=>'Method not allowed.']);exit;}try{verify_csrf();$eventId=(int)($_POST['event_id']??0);$code=trim($_POST['code']??'');if($eventId<1||$code==='')throw new RuntimeException('Select an event and provide a ticket code.');if(!preg_match('/^[A-Za-z0-9-]{6,64}$/',$code))throw new RuntimeException('That does not look like a valid ticket code.');$pdo->beginTransaction();$s=$pdo->prepare('SELECT r.*,u.name participant,e.title event_title,e.status event_status,e.event_date FROM registrations r JOIN users u ON u.id=r.user_id JOIN events e ON e.id=r.event_id WHERE r.event_id=? AND (r.entry_code=? OR r.qr_token=?) FOR UPDATE');$s->execute([$eventId,$code,$code]);$r=$s->fetch();if(!$r)throw new RuntimeException('Invalid ticket, or this ticket belongs to a different event.');if($r['status']!=='valid')throw new RuntimeException('This registration is not valid.');if($r['event_status']==='cancelled'||$r['event_status']==='draft')throw new RuntimeException('This event is not available for check-in.');$s=$pdo->prepare('SELECT id FROM checkins WHERE registration_id=? FOR UPDATE');$s->execute([$r['id']]);if($s->fetch())throw new RuntimeException('Duplicate check-in blocked — this participant has already been checked in.');$s=$pdo->prepare('INSERT INTO checkins(registration_id,event_id,staff_admin_id,entry_code) VALUES(?,?,?,?)');$s->execute([$r['id'],$eventId,$_SESSION['admin_id'],$r['entry_code']]);log_action($pdo,'checkin.success','Registration '.$r['registration_code'].' checked into event '.$eventId);$pdo->commit();echo json_encode(['ok'=>true,'message'=>'Check-in successful. Welcome, '.$r['participant'].'!']);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$message=$e instanceof RuntimeException?$e->getMessage():'Verification failed. Please try again.';echo json_encode(['ok'=>false,'message'=>$message]);}
